3181:      rt.url = NULL;
3182:    }
3183:  else if (rt.subtype == RING_TRUST_KEY
3184:           && (ctx->last_pkt.pkttype == PKT_PUBLIC_KEY
3185:               || ctx->last_pkt.pkttype == PKT_SECRET_KEY))
